import{_ as t,o as n,c as e,ag as s}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-10（生物医学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-10-10.md","filePath":"topics/biomedicine/science-daily-2026-10-10.md"}'),r={name:"topics/biomedicine/science-daily-2026-10-10.md"};function i(c,o,a,l,g,d){return n(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-10-10-生物医学" tabindex="-1">科学日报 · 2026-10-10（生物医学） <a class="header-anchor" href="#科学日报-·-2026-10-10-生物医学" aria-label="Permalink to &quot;科学日报 · 2026-10-10（生物医学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-10.md</code> — 第33期</p></blockquote><hr><h2 id="高尔基体来源的-pi-3-4-p2-囊泡驱动线粒体融合-science" tabindex="-1">高尔基体来源的 PI(3,4)P₂ 囊泡驱动线粒体融合（Science） <a class="header-anchor" href="#高尔基体来源的-pi-3-4-p2-囊泡驱动线粒体融合-science" aria-label="Permalink to &quot;高尔基体来源的 PI(3,4)P₂ 囊泡驱动线粒体融合（Science）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-10.md</code> ｜ DOI: 10.1126/science.adx9628</p></blockquote><ul><li>背景：线粒体靠不断改变形态来调控细胞命运。其<strong>分裂</strong>依赖与<strong>内质网（ER）、溶酶体、反式高尔基网络来源囊泡</strong>的互作来完成膜剪切；但细胞器之间的接触如何调控线粒体<strong>融合</strong>，此前基本未知。</li><li>方法/发现：鉴定出富含<strong>磷脂酰肌醇 3,4-二磷酸 [PI(3,4)P₂]</strong> 的<strong>高尔基体来源囊泡</strong>调控融合——这些囊泡被招募到 <strong>ER 与 mitofusin 标记的融合位点</strong>。</li><li>证据：生成 PI(3,4)P₂ 的 <strong>II 类 PI3-激酶亚型 α/β（PI3K-C2α/C2β）</strong> 缺失会损害融合，坐实了&quot;脂质身份 → 融合位点模板&quot;的因果链。</li><li>洞察：线粒体是被内共生&quot;驯化&quot;过的细胞器（参 <code>chloroplast-endosymbiosis.md</code>），其融合长期被视作&quot;自身蛋白（Mfn/OPA1）主导&quot;；本工作把<strong>另一套细胞器的脂质囊泡</strong>纳入融合的调控网络——<strong>细胞器不是孤立机器，而是由跨细胞器接触网络协同决定形态</strong>。与本库&quot;功能是分布/系综的统计属性&quot;母题同源：融合与否取决于<strong>接触位点的局域脂质组成</strong>，而非某个单一开关。</li></ul><h2 id="细菌外膜-lps-跨膜转运的结构开关-nature" tabindex="-1">细菌外膜 LPS 跨膜转运的结构开关（Nature） <a class="header-anchor" href="#细菌外膜-lps-跨膜转运的结构开关-nature" aria-label="Permalink to &quot;细菌外膜 LPS 跨膜转运的结构开关（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-10.md</code> ｜ DOI: 10.1038/s41586-026-11129-8</p></blockquote><ul><li>背景：革兰氏阴性菌的外膜几乎不通透，赋予其对多种抗生素的<strong>天然耐药</strong>；外膜是不对称双层——内叶磷脂、外叶<strong>脂多糖（LPS）</strong>。</li><li>已知：一台名为 <strong>LptB₂FGCADE</strong> 的机器沿&quot;<strong>蛋白桥</strong>&quot;把 LPS 从内膜送到外膜；LPS <strong>生物合成</strong>会被调控以防在内膜中毒性累积，但<strong>跨 Lpt 桥的转运</strong>是否也受调控一直不清。</li><li>方法：解析跨包膜 Lpt 复合体在<strong>无 LPS / 结合 LPS / 结合 ATP</strong> 三种状态的结构，外加一个<strong>部分桥</strong>结构，并结合生化实验。</li><li>结论：<strong>Lpt 桥的组装</strong>会以<strong>依赖 LPS</strong> 的方式触发 <strong>LptC 跨膜螺旋（TM-LptC）移动</strong>，从而增加 <strong>ATP 结合与水解</strong>；体内 LPS 转运也确需桥的形成。</li><li>意义：把&quot;<strong>转运环节本身</strong>&quot;确认为一个可调控、可成药的开关，为绕过革兰氏阴性菌外膜屏障的<strong>新抗生素靶点</strong>提供了结构基础（与 <code>2026-q3-breakthroughs.md</code> 的&quot;感染/通用疫苗&quot;线同属抗感染前沿）。</li></ul><h2 id="靶向-zfp423-的-rna-产热疗法-在-glp-1-减重中保住肌肉-pnas" tabindex="-1">靶向 ZFP423 的 RNA 产热疗法：在 GLP-1 减重中保住肌肉（PNAS） <a class="header-anchor" href="#靶向-zfp423-的-rna-产热疗法-在-glp-1-减重中保住肌肉-pnas" aria-label="Permalink to &quot;靶向 ZFP423 的 RNA 产热疗法：在 GLP-1 减重中保住肌肉（PNAS）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-10.md</code> ｜ DOI: 10.1073/pnas.2618845123</p></blockquote><ul><li>痛点：<strong>GLP-1 受体激动剂（GLP-1RA）</strong> 能减重、改善代谢病，但减重常伴随<strong>能量消耗下降、瘦体重流失</strong>，停药后易出现<strong>以脂肪为主的快速反弹</strong>——&quot;掉的多是肌肉、回来的是脂肪&quot;。</li><li>假设：用药理学手段<strong>激活脂肪产热</strong>，可专门针对脂肪、以&quot;提高能量消耗&quot;来补充&quot;抑制食欲&quot;。</li><li>方法：基于&quot;<strong>饮食诱导产热由锌指蛋白 423（ZFP423）通路介导</strong>&quot;的发现，开发<strong>脂肪定向反义寡核苷酸（ASO）</strong>，靶向 <strong>ZFP423</strong>——棕色/米色脂肪细胞身份的<strong>转录抑制因子</strong>。</li><li>数据：在瘦与饮食诱导肥胖小鼠中，每周 Zfp423 ASO 诱导<strong>白色脂肪米色化</strong>，提高体温与耗氧，改善糖稳态、胰岛素敏感性、脂质代谢、线粒体呼吸与<strong>肝脂肪变性</strong>；与 <strong>司美格鲁肽（semaglutide）</strong> 联用时，减重与减脂幅度<strong>大于任一单药</strong>，且<strong>保住瘦体重</strong>。</li><li>意义：把&quot;<strong>代谢更健康的减重</strong>&quot;变成可操作目标——<strong>RNA 药 + GLP-1 联用</strong>分工：一个降食欲、一个提产热。与 <code>home-fat-burning.md</code>（提升静息代谢/产热）的健身直觉在分子层合流：<strong>减脂的关键不只是&quot;少吃&quot;，而是&quot;把能耗拉上去&quot;</strong>。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ 第33期 科学板块</p></blockquote><p>关键词：线粒体融合、PI(3,4)P₂、高尔基体囊泡、PI3K-C2α/C2β、mitofusin、内质网接触；LPS 转运、LptB₂FGCADE、LptC、外膜、革兰氏阴性菌、抗生素耐药；GLP-1RA、司美格鲁肽、ZFP423、反义寡核苷酸、脂肪米色化、产热、瘦体重、代谢健康 关联：<code>topics/biomedicine/chloroplast-endosymbiosis.md</code>（线粒体/叶绿体同源——细胞器被驯化与协同）、<code>topics/biomedicine/2026-q3-breakthroughs.md</code>（感染/抗感染线）、<code>topics/fitness/home-fat-burning.md</code>（产热与静息代谢——GLP-1 联用篇的健身侧对读）、<code>topics/biomedicine/science-daily-2026-10-09.md</code>（前一日生物医学板块）</p>',15)])])}const q=t(r,[["render",i]]);export{p as __pageData,q as default};
